# Offline mock validation of parsing + summation logic (no canned data in production code;
# this is a local transport stub for verification only).
import json, io, os
import prices

calls = []
def fake_urlopen(req, timeout=5):
    calls.append(req.full_url)
    sku = req.full_url.rsplit('/', 1)[-1]
    body = {"price": {"A100": 12.5, "B200": 17.5}[sku]}
    return io.BytesIO(json.dumps(body).encode())

import urllib.request
urllib.request.urlopen = fake_urlopen
assert prices.get_total(["A100"]) == 12.5
assert prices.get_total(["A100", "B200"]) == 30.0
assert prices.get_total([]) == 0
print("mock OK:", calls)

# nested shape {"price": {"amount": ...}}
def fake_nested(req, timeout=5):
    sku = req.full_url.rsplit('/', 1)[-1]
    amt = {"A100": 12.5, "B200": 17.5}[sku]
    return io.BytesIO(json.dumps({"price": {"amount": amt, "currency": "USD"}}).encode())
urllib.request.urlopen = fake_nested
assert prices.get_total(["A100", "B200"]) == 30.0
print("nested-shape OK")

# header is sent when PRICING_KEY is set
seen = {}
def fake_hdrs(req, timeout=5):
    seen.update(req.header_items())
    return io.BytesIO(b'{"price": 1.0}')
urllib.request.urlopen = fake_hdrs
os.environ["PRICING_KEY"] = "dummy"
prices.get_price("A100")
assert ("X-pricing-key", "dummy") in [(k, v) for k, v in seen.items()], seen
print("header OK")
EOF"}

